-- Deterministic seed for local testing (single test user).
-- Test user id used by the integration tests:
--   00000000-0000-0000-0000-000000000001
--
-- Applied automatically by `supabase start` / `supabase db reset`.
-- Rows are hand-crafted to exercise GET /expenses query combinations:
--   - dates spanning 2026-06 / 07 / 08 (date range)
--   - amounts incl. 0, NULL and ties (min/max range, sort, nulls-last)
--   - titles incl. duplicates, lowercase 'amazon', and literal '%' / '_'
--     (case-insensitive substring + wildcard escaping)
--   - multiple methods / categories, plus one income row

truncate table expenses, categories, methods restart identity cascade;



